from collections import Counter

def transform(grid):
    if not grid:
        return grid

    h, w = len(grid), len(grid[0])

    # Count all colors
    counts = Counter()
    for row in grid:
        for c in row:
            counts[c] += 1

    # Get most, second, and least common
    sorted_colors = sorted(counts.keys(), key=lambda x: -counts[x])
    most = sorted_colors[0]
    second = sorted_colors[1]
    least = sorted_colors[-1]

    # Find positions of second
    second_positions = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == second]

    # Second positions are special cells
    # Mark rows and columns that have second positions
    second_rows = {r for r, c in second_positions}
    second_cols = {c for r, c in second_positions}

    # Create output grid
    output = [[0]*w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            val = grid[r][c]

            # If this cell is a second position
            if (r, c) in second_positions:
                output[r][c] = 4
            # If in rows with second positions, mark stripe
            elif r in second_rows:
                output[r][c] = least
            # If in columns with second positions, mark stripe
            elif c in second_cols:
                output[r][c] = least
            # Otherwise, most common becomes least
            elif val == most:
                output[r][c] = least
            # second cells become least
            elif val == second:
                output[r][c] = least
            # least cells become 4
            else:
                output[r][c] = 4

    return output

# Test demos
with open('/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-7/play/users/u042/system/state/workspace/programs/task-d4079843.json') as f:
    data = json.load(f)

for i, pair in enumerate(data):
    inp = pair['input']
    out = pair['output']
    pred = transform(inp)
    match = pred == out
    print(f"Demo {i+1}: {'PASS' if match else 'FAIL'}")
    if not match:
        for r in range(min(len(pred), len(out))):
            if r < len(pred) and r < len(out):
                if pred[r] != out[r]:
                    print(f"  Row {r}: pred={pred[r]}, actual={out[r]}")
    print()

